// We want to be flexible with DataConnection and DataConnectionInit 
            // So we have three sources of truth here: 
            // DevConnectionStrings/DataConnection from json -- this is a override for development
            // ConnectionStrings.DataConnection from db      -- the right place, in the configuration database
            // ConnectionStrings/DataConnection from json    -- default value as a fallback.
            // DataConnectionInit is an initial command isseud to the DataConnection database after opening. 
            // Ususally this contains a statement to setup the right schema for the session and it means 
            // we use it with the DataConnection from the same source. 
            // So we read DataConnection and DataConnectionInit and ignore DataConnectionInit if it's from a different source.
            Bovis.Logging.Logger.Default.LogInformation("BC130680200I setting up Bovis database connection");
            // read data connection. 
            // Priority is 
            int dataUrlSrc = 0;
            var dataUrl = builder.Configuration.GetSection("DevConnectionStrings")["DataConnection"];
            if (dataUrl != null) { dataUrlSrc = 1; goto found; }
            dataUrl = configStore.GetProperty("ConnectionStrings.DataConnection");
            if (dataUrl != null) { dataUrlSrc = 2; goto found; }
            dataUrl = builder.Configuration.GetConnectionString("DataConnection");
            if (dataUrl != null) { dataUrlSrc = 3; goto found; }
            throw new InvalidOperationException("BC25F86C3E3E Connection string 'DataConnection' not found.");
        found:
            Bovis.Logging.Logger.Default.LogInformation("BC966B3E63CI Found Bovis connection string {dataUrl}", dataUrl);
            int dataInitSrc = 0;
            var dataInit = builder.Configuration.GetSection("DevConnectionStrings")["DataConnectionInit"];
            if (dataInit != null) { dataInitSrc = 1; goto found2; }
            dataInit = configStore.GetProperty("ConnectionStrings.DataConnectionInit");
            if (dataInit != null) { dataInitSrc = 2; goto found2; }
            dataInit = builder.Configuration.GetConnectionString("DataConnectionInit");
            if (dataInit != null) { dataInitSrc = 3; goto found2; }
        found2:
            // If the sources differ, ignore the init command to avoid mismatched setups.
            if (dataUrlSrc != dataInitSrc) dataInit = null;
            var dbConnection = new ConnectionUrl(dataUrl).CreateConnection();

            if (builder.Configuration.GetConnectionString("DataConnectionWrapper") is string s)
                if (s == "LoggingDbConnection")
                {
                    dbConnection = new Util.LoggingDbConnection(dbConnection, Bovis.Logging.Logger.Make("LoggingDb"));
                }

            var backend = configStore.GetProperty("ConnectionStrings.DataBackend");
            backend ??= builder.Configuration.GetConnectionString("DataBackend");
            backend ??= "Bohris";

            Logging.Logger.Info($"BC3AA2CC1AAI Setting up Backend {backend}");
            IBovisBackend? backendImpl = null;
            switch (backend)
            {
                case "Bohris":
                    {
                        backendImpl = new Bovis.Web.Bohris.Backend();
                        break;
                    }
                case "LBEG":
                    {
                        backendImpl = new Bovis.Web.LBEG.Backend();
                        break;
                    }
                default:
                    throw new InvalidOperationException($"BC7811A53F8E Unsupported DataBackend '{backend}'");
            }
            builder.Services.AddSingleton<Bovis.Interfaces.IBovisBackend>(backendImpl);
            backendImpl.Setup(builder.Services, configStore, dbConnection, dataInit);
            Bovis.Logging.Logger.Default.LogInformation("BC12F626004I connection to Bovis database established");
        }
        //===========

        return builder;
    }

